import 'package:flutter/material.dart';\nimport 'package:flutter_test/flutter_test.dart';\n\nFuture<void> iCheckTheSanitizeExportOption(WidgetTester tester) async {\n  await tester.tap(find.byKey(const Key('sanitize_export_checkbox')));\n  await tester.pumpAndSettle();\n  \n  // Verify the checkbox is now checked\n  final checkbox = tester.widget<CheckboxListTile>(find.byKey(const Key('sanitize_export_checkbox')));\n  expect(checkbox.value, isTrue);\n}